impl Deploy for Account {
    async fn deploy_uups(&self) -> Result<Receipt> {
        self.as_deployer()
            .with_constructor(constructor!(self.address()))
            .deploy()
            .await
    }

    async fn deploy_uups_new_version(&self) -> Result<Receipt> {
        self.as_deployer()
            .with_example_name("uups-proxy-new-version")
